def extract_municipality(address):
    if not address:
        return ""

    text = str(address).strip()

    match = re.search(
        r"[都道府県](.+?[市区町村])",
        text
    )

    if match:
        return match.group(1)

    return ""


def calculate_unit_price(df):
    result = df.copy()

    if "価格" in result.columns and "面積" in result.columns:

        price = pd.to_numeric(
            result["価格"],
            errors="coerce"
        )

        area = pd.to_numeric(
            result["面積"],
            errors="coerce"
        )

        result["㎡単価"] = (
            price /
            area.replace(0, pd.NA)
        )

    return result


def filter_comparison_properties(
    comparison_data,
    target_type,
    target_address,
    target_area,
    target_age
):

    data = comparison_data.copy()

    if "物件種別" in data.columns:

        data = data[
            data["物件種別"]
            .astype(str)
            .str.strip()
            == str(target_type).strip()
        ]

    if len(data) == 0:
        return data, "物件種別のみ"

    target_municipality = extract_municipality(
        target_address
    )

    if "住所" in data.columns and target_municipality:

        municipalities = data["住所"].apply(
            extract_municipality
        )

        same_municipality = data[
            municipalities == target_municipality
        ]

        if len(same_municipality) >= 3:
            data = same_municipality

    if "面積" in data.columns and target_area > 0:

        data = data.copy()

        data["_比較面積"] = pd.to_numeric(
            data["面積"],
            errors="coerce"
        )

        area_min = target_area * 0.70
        area_max = target_area * 1.30

        area_filtered = data[
            data["_比較面積"].between(
                area_min,
                area_max
            )
        ]

        if len(area_filtered) >= 3:
            data = area_filtered

    if "築年" in data.columns:

        data = data.copy()

        data["_比較築年"] = pd.to_numeric(
            data["築年"],
            errors="coerce"
        )

        age_filtered = data[
            data["_比較築年"].between(
                target_age - 15,
                target_age + 15
            )
        ]

        if len(age_filtered) >= 3:
            data = age_filtered

    for column in [
        "_比較面積",
        "_比較築年"
    ]:

        if column in data.columns:

            data = data.drop(
                columns=[column]
            )

    return data, "自動絞り込み"


def calculate_manufacturer_summary(data):

    required_columns = [
        "住宅メーカー",
        "価格",
        "面積"
    ]

    if not all(
        column in data.columns
        for column in required_columns
    ):
        return pd.DataFrame()

    work = data.copy()

    work["価格"] = pd.to_numeric(
        work["価格"],
        errors="coerce"
    )

    work["面積"] = pd.to_numeric(
        work["面積"],
        errors="coerce"
    )

    work["メーカー別㎡単価"] = (
        work["価格"]
        /
        work["面積"].replace(
            0,
            pd.NA
        )
    )

    work = work.dropna(
        subset=[
            "住宅メーカー",
            "メーカー別㎡単価"
        ]
    )

    if len(work) == 0:
        return pd.DataFrame()

    summary = (
        work[
            [
                "住宅メーカー",
                "メーカー別㎡単価"
            ]
        ]
        .groupby("住宅メーカー")
        .agg({
            "メーカー別㎡単価": [
                "mean",
                "count"
            ]
        })
        .reset_index()
    )

    summary.columns = [
        "住宅メーカー",
        "平均㎡単価",
        "件数"
    ]

    return summary


def calculate_manufacturer_factor(
    comparison_data,
    target_manufacturer
):

    if not target_manufacturer:
        return 1.0, 0

    summary = calculate_manufacturer_summary(
        comparison_data
    )

    if summary.empty:
        return 1.0, 0

    target_rows = summary[
        summary["住宅メーカー"]
        .astype(str)
        .str.strip()
        ==
        str(target_manufacturer).strip()
    ]

    if len(target_rows) == 0:
        return 1.0, 0

    target_count = int(
        target_rows.iloc[0]["件数"]
    )

    if target_count < 2:
        return 1.0, target_count

    overall_unit_price = (
        pd.to_numeric(
            comparison_data["価格"],
            errors="coerce"
        )
        /
        pd.to_numeric(
            comparison_data["面積"],
            errors="coerce"
        ).replace(
            0,
            pd.NA
        )
    )

    overall_median = (
        overall_unit_price.median()
    )

    if (
        pd.isna(overall_median)
        or
        overall_median <= 0
    ):
        return 1.0, target_count

    manufacturer_unit_price = float(
        target_rows.iloc[0]["平均㎡単価"]
    )

    factor = (
        manufacturer_unit_price
        /
        overall_median
    )

    factor = max(
        0.90,
        min(
            1.10,
            factor
        )
    )

    return factor, target_count


