# =========================================================
# 物件評価
# =========================================================

st.markdown(
    '<div class="section-title">💰 価格チェック</div>',
    unsafe_allow_html=True
)

st.markdown(
    '<div class="section-description">'
    '入力内容と比較データから参考価格を計算します。結果は価格差まで分かりやすく表示します。'
    '</div>',
    unsafe_allow_html=True
)

evaluate_button = st.button(
    "💰 価格をチェック",
    type="primary",
    use_container_width=True
)


if evaluate_button:

    if target_price <= 0:

        st.warning(
            "販売価格を入力してください。"
        )

        st.stop()

    if target_area <= 0:

        st.warning(
            "面積を入力してください。"
        )

        st.stop()

    comparison_data = (
        st.session_state.get(
            "comparison_data"
        )
    )

    if comparison_data is None:

        st.warning(
            "先に比較物件のExcelを読み込んでください。"
        )

        st.stop()

    # 利用状況計測（将来の収益化判断用）
    register_usage_event("property_evaluation")

    filtered_comparison, filter_method = (
        filter_comparison_properties(
            comparison_data,
            target_type,
            target_address,
            target_area,
            target_age
        )
    )

    if len(filtered_comparison) < 2:

        if "物件種別" in comparison_data.columns:

            filtered_comparison = (
                comparison_data[
                    comparison_data[
                        "物件種別"
                    ]
                    .astype(str)
                    ==
                    str(target_type)
                ]
            )

        else:

            filtered_comparison = (
                comparison_data.copy()
            )

        filter_method = "物件種別のみ"

    comparison_unit_prices = (
        pd.to_numeric(
            filtered_comparison["㎡単価"],
            errors="coerce"
        )
        .replace(
            [
                float("inf"),
                -float("inf")
            ],
            pd.NA
        )
        .dropna()
    )

    if len(comparison_unit_prices) < 2:

        st.warning(
            "比較できる物件が2件以上ありません。"
        )

        st.stop()

    median_unit_price = (
        comparison_unit_prices.median()
    )

    current_year = 2026

    building_age = max(
        0,
        current_year - target_age
    )

    age_adjustment = max(
        0.70,
        1 - building_age * 0.01
    )

    base_estimated_price = (
        median_unit_price
        *
        target_area
        *
        age_adjustment
    )

    manufacturer_factor, manufacturer_count = (
        calculate_manufacturer_factor(
            filtered_comparison,
            target_manufacturer
        )
    )

    manufacturer_adjustment_used = (
        manufacturer_count >= 2
    )

    if manufacturer_adjustment_used:

        estimated_price = (
            base_estimated_price
            *
            manufacturer_factor
        )

    else:

        estimated_price = (
            base_estimated_price
        )

    price_difference = (
        target_price
        -
        estimated_price
    )

    if estimated_price > 0:

        target_ratio = (
            target_price
            /
            estimated_price
        )

    else:

        target_ratio = 1.0

    if target_ratio <= 0.90:

        evaluation = "A"

    elif target_ratio <= 1.10:

        evaluation = "B"

    else:

        evaluation = "C"

    evaluation_label = {
        "A": "お買い得",
        "B": "妥当な価格",
        "C": "割高の可能性"
    }[evaluation]


    # =====================================================
    # 評価結果表示
    # =====================================================

    st.markdown(
        '<div class="section-title">📋 チェック結果</div>',
        unsafe_allow_html=True
    )

    st.markdown(
        '<div class="result-card">',
        unsafe_allow_html=True
    )

    result_col1, result_col2 = st.columns(
        2
    )

    with result_col1:

        st.markdown(
            '<div class="result-label">'
            '現在の販売価格'
            '</div>',
            unsafe_allow_html=True
        )

        st.markdown(
            '<div class="result-price">'
            f'{target_price:,.0f}万円'
            '</div>',
            unsafe_allow_html=True
        )

    with result_col2:

        st.markdown(
            '<div class="result-label">'
            '比較データからの参考価格'
            '</div>',
            unsafe_allow_html=True
        )

        st.markdown(
            '<div class="result-price">'
            f'{estimated_price:,.0f}万円'
            '</div>',
            unsafe_allow_html=True
        )

    st.divider()

    result_col1, result_col2 = st.columns(
        2
    )

    with result_col1:

        st.metric(
            "参考価格との差額",
            f"{price_difference:+,.0f}万円"
        )

    with result_col2:

        st.metric(
            "価格評価",
            evaluation_label
        )

    st.markdown(
        '</div>',
        unsafe_allow_html=True
    )


    # =====================================================
    # 将来の収益化枠
    # =====================================================
    # 現在は各フラグがFalseなので何も表示されません。
    # 将来ONにすると、無料ユーザーの評価結果の後に表示できます。

    show_video_monetization_slot()
    show_affiliate_slot()


    # =====================================================
    # 比較条件
    # =====================================================

    st.markdown(
        "#### 📊 比較条件"
    )

    info_col1, info_col2, info_col3 = st.columns(
        3
    )

    with info_col1:

        st.markdown(
            '<div class="info-card">'
            '<div class="mini-label">比較方法</div>'
            f'<strong>{filter_method}</strong>'
            '</div>',
            unsafe_allow_html=True
        )

    with info_col2:

        st.markdown(
            '<div class="info-card">'
            '<div class="mini-label">比較物件数</div>'
            f'<strong>{len(filtered_comparison)}件</strong>'
            '</div>',
            unsafe_allow_html=True
        )

    with info_col3:

        st.markdown(
            '<div class="info-card">'
            '<div class="mini-label">㎡単価中央値</div>'
            f'<strong>{median_unit_price:,.1f}万円/㎡</strong>'
            '</div>',
            unsafe_allow_html=True
        )


    # =====================================================
    # メーカー情報
    # =====================================================

    if (
        target_manufacturer
        != "選択してください"
    ):

        st.markdown(
            "#### 🏢 住宅メーカー"
        )

        if manufacturer_adjustment_used:

            manufacturer_percent = (
                (
                    manufacturer_factor
                    - 1
                )
                *
                100
            )

            st.success(
                f"{target_manufacturer}の"
                f"比較データ{manufacturer_count}件を使用し、"
                f"参考価格に{manufacturer_percent:+.1f}%の"
                "メーカー補正を適用しています。"
            )

        else:

            st.info(
                f"{target_manufacturer}の比較データが"
                "まだ少ないため、メーカー補正は"
                "適用していません。"
            )


    # =====================================================
    # 評価理由
    # =====================================================

    if evaluation == "A":

        evaluation_reason = (
            f"築年を考慮した参考価格は"
            f"{estimated_price:,.0f}万円です。"
            f"現在価格は参考価格より"
            f"{(1 - target_ratio) * 100:.1f}%低い水準です。"
        )

    elif evaluation == "B":

        evaluation_reason = (
            f"築年を考慮した参考価格は"
            f"{estimated_price:,.0f}万円です。"
            f"現在価格は参考価格に対して"
            f"{target_ratio * 100:.1f}%の水準です。"
        )

    else:

        evaluation_reason = (
            f"築年を考慮した参考価格は"
            f"{estimated_price:,.0f}万円です。"
            f"現在価格は参考価格より"
            f"{(target_ratio - 1) * 100:.1f}%高い水準です。"
        )

    st.markdown(
        "#### 💡 評価の内容"
    )

    st.info(
        evaluation_reason
    )


    # =====================================================
    # 比較物件
    # =====================================================

    with st.expander(
        f"比較に使用した物件を見る（{len(filtered_comparison)}件）"
    ):

        st.dataframe(
            filtered_comparison,
            use_container_width=True
        )


    # =====================================================
    # 注意書き
    # =====================================================

    st.caption(
        "※表示する価格は参考値です。購入・売却の最終判断は、現地状況や専門家の査定などもあわせてご確認ください。"
        "実際の成約価格・査定価格とは異なる場合があります。"
    )

    st.caption(
        "※今後、国土交通省の取引データ等を接続することで、"
        "より高度な価格推定モデルへ発展できます。"
    )
